import { Buffer } from 'node:buffer';
export default function incoming({headers,body,expectedAuthorization,companyId}) {
 const configured=typeof expectedAuthorization==='string'?/^Basic ([A-Za-z0-9+/]+={0,2})$/.exec(expectedAuthorization.trim()):null;
 const secret=configured?Buffer.from(configured[1],'base64').toString('utf8'):'';if(!/^[^:]+:.+$/.test(secret)||/[\r\n]/.test(secret))throw Error('Configure the webhook Basic authorization secret');
 const h=Object.entries(headers||{}).filter(([k])=>k.toLowerCase()==='authorization'),match=h.length===1&&typeof h[0][1]==='string'?/^Basic +([A-Za-z0-9+/]+={0,2})$/i.exec(h[0][1].trim()):null,actual=match?Buffer.from(match[1],'base64').toString('utf8'):'';let diff=secret.length^actual.length;for(let i=0;i<Math.max(secret.length,actual.length);i++)diff|=(secret.charCodeAt(i)||0)^(actual.charCodeAt(i)||0);
 if(diff)return{accepted:false,process:false,statusCode:401,orgId:1,body:{error:'Unauthorized'}};
 if(typeof companyId!=='string'||!/^\d+$/.test(companyId))throw Error('Configure your Pipedrive company ID');
 const meta=body?.meta,data=body?.data,previous=body?.previous;if(!meta||meta.version!=='2.0'||meta.entity!=='deal'||meta.action!=='change'||String(meta.company_id)!==companyId||!data||!previous||typeof previous!=='object')return{accepted:false,process:false,statusCode:400,orgId:1,body:{error:'Invalid event'}};
 if(!Object.prototype.hasOwnProperty.call(previous,'won_time'))return{accepted:true,process:false,statusCode:200,orgId:1,body:{status:'ignored'}};
 if(!Object.prototype.hasOwnProperty.call(data,'won_time'))return{accepted:false,process:false,statusCode:400,orgId:1,body:{error:'Missing won time'}};
 if(previous.won_time===data.won_time)return{accepted:true,process:false,statusCode:200,orgId:1,body:{status:'ignored'}};
 const orgId=Number(data.org_id);if(!Number.isSafeInteger(orgId)||orgId<=0)return{accepted:false,process:false,statusCode:400,orgId:1,body:{error:'Missing organization'}};
 return {accepted:true,process:true,statusCode:200,orgId,body:{status:'accepted'}};
}

